/**
 * AD Sync Dispatcher Lambda
 *
 * Triggered by EventBridge on schedule (e.g. every 6 hours).
 * Queries amfa-configtable GSI (configtype-index) for all tenants with AD sync enabled,
 * then invokes the ad-sync-worker Lambda for each tenant asynchronously.
 */

import { DynamoDBClient, QueryCommand } from '@aws-sdk/client-dynamodb';
import { LambdaClient, InvokeCommand } from '@aws-sdk/client-lambda';

const dynamodb = new DynamoDBClient({});
const lambda = new LambdaClient({});

const STAGGER_DELAY_MS = 500;

export const handler = async (event) => {
  const startTime = new Date().toISOString();
  console.log(JSON.stringify({ level: "INFO", event: "DISPATCHER_STARTED", timestamp: startTime, trigger: event?.source || "manual" }));

  try {
    // Query GSI for all adSyncConfig items (efficient — reads only matching items)
    const allItems = [];
    let lastEvaluatedKey = undefined;
    do {
      const queryResult = await dynamodb.send(new QueryCommand({
        TableName: process.env.CONFIG_TABLE,
        IndexName: "configtype-index",
        KeyConditionExpression: "configtype = :ct",
        ExpressionAttributeValues: { ":ct": { S: "adSyncConfig" } },
        ...(lastEvaluatedKey ? { ExclusiveStartKey: lastEvaluatedKey } : {}),
      }));
      allItems.push(...(queryResult.Items || []));
      lastEvaluatedKey = queryResult.LastEvaluatedKey;
    } while (lastEvaluatedKey);

    const allTenants = allItems.map((item) => {
      const config = JSON.parse(item.value?.S || "{}");
      return { tenantId: item.id.S, config };
    });

    const enabledTenants = allTenants.filter((t) => t.config.enabled === true);

    console.log(JSON.stringify({
      level: "INFO", event: "TENANTS_SCANNED",
      totalConfigs: allTenants.length, enabledCount: enabledTenants.length,
      enabledTenants: enabledTenants.map((t) => t.tenantId),
    }));

    if (enabledTenants.length === 0) {
      console.log(JSON.stringify({ level: "INFO", event: "NO_TENANTS_ENABLED", message: "No tenants with AD sync enabled" }));
      return { statusCode: 200, body: { dispatched: 0, message: "no_tenants_enabled" } };
    }

    // Fan-out: invoke worker for each tenant with stagger delay
    const results = [];
    for (let i = 0; i < enabledTenants.length; i++) {
      const { tenantId } = enabledTenants[i];

      try {
        console.log(JSON.stringify({
          level: "DEBUG", event: "DISPATCHING", tenantId,
          index: i + 1, total: enabledTenants.length,
        }));

        await lambda.send(new InvokeCommand({
          FunctionName: process.env.SYNC_WORKER_FUNCTION_NAME,
          InvocationType: "Event",
          Payload: JSON.stringify({ tenantId }),
        }));

        results.push({ tenantId, status: "dispatched" });

        console.log(JSON.stringify({ level: "INFO", event: "DISPATCHED", tenantId }));

        // Stagger to avoid Cognito API throttling
        if (i < enabledTenants.length - 1) {
          await new Promise((r) => setTimeout(r, STAGGER_DELAY_MS));
        }
      } catch (err) {
        console.error(JSON.stringify({
          level: "ERROR", event: "DISPATCH_FAILED", tenantId,
          error: err.message,
        }));
        results.push({ tenantId, status: "failed", error: err.message });
      }
    }

    const dispatched = results.filter((r) => r.status === "dispatched").length;
    const failed = results.filter((r) => r.status === "failed").length;

    console.log(JSON.stringify({
      level: "INFO", event: "DISPATCHER_COMPLETE",
      dispatched, failed, totalEnabled: enabledTenants.length,
    }));

    return {
      statusCode: 200,
      body: { dispatched, failed, tenants: results },
    };
  } catch (err) {
    console.error(JSON.stringify({
      level: "ERROR", event: "DISPATCHER_FAILED",
      error: err.message, stack: err.stack,
    }));
    return { statusCode: 500, body: { error: err.message } };
  }
};
